#!/usr/bin/env python3
"""Summarize Go statement profiles without double-counting cross-package blocks."""
import argparse
import json
from pathlib import Path


def read_profiles(paths):
    blocks = {}
    for path in paths:
        lines = Path(path).read_text().splitlines()
        if not lines or lines[0] not in ("mode: set", "mode: count", "mode: atomic"):
            raise ValueError(f"invalid coverage header: {path}")
        for line in lines[1:]:
            location, statements, count = line.rsplit(maxsplit=2)
            statements, count = int(statements), int(count)
            if statements < 0 or count < 0:
                raise ValueError(f"negative coverage count: {line}")
            previous = blocks.get(location)
            if previous and previous[0] != statements:
                raise ValueError(f"incompatible statement counts: {location}")
            blocks[location] = (statements, bool(count) or bool(previous and previous[1]))
    if not blocks:
        raise ValueError("empty coverage profile")
    return blocks


def summarize(blocks):
    files = {}
    for location, (statements, hit) in blocks.items():
        # rsplit also handles drive letters in absolute Windows paths.
        name = location.rsplit(":", 1)[0]
        row = files.setdefault(name, {"statements": 0, "covered": 0})
        row["statements"] += statements
        row["covered"] += statements if hit else 0
    totals = {key: sum(row[key] for row in files.values()) for key in ("statements", "covered")}
    for row in [totals, *files.values()]:
        row["percent"] = 100 * row["covered"] / row["statements"] if row["statements"] else 100.0
    return {"metric": "Go statements", "totals": totals, "files": dict(sorted(files.items()))}


def compare(current, baseline):
    """Compare only equivalent configurations; do not compare macOS with Linux."""
    if any(report["environment"].get("tests_exit_code") != 0 for report in (current, baseline)):
        raise ValueError("coverage comparison requires two passing test runs")
    for key in ("go_version", "platform", "tags", "race", "scope"):
        if current["environment"].get(key) != baseline["environment"].get(key):
            raise ValueError(f"baseline configuration differs: {key}")
    return current["totals"]["percent"] - baseline["totals"]["percent"]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("profiles", nargs="+")
    parser.add_argument("--metadata", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--merged-profile", required=True)
    parser.add_argument("--baseline", help="optional same-platform/build JSON report; fail on a coverage decrease")
    args = parser.parse_args()
    blocks = read_profiles(args.profiles)
    report = summarize(blocks)
    report["environment"] = json.loads(Path(args.metadata).read_text())
    if args.baseline:
        report["delta_percentage_points"] = compare(report, json.loads(Path(args.baseline).read_text()))
    Path(args.output).write_text(json.dumps(report, indent=2) + "\n")
    Path(args.merged_profile).write_text("mode: set\n" + "".join(
        f"{location} {statements} {int(hit)}\n"
        for location, (statements, hit) in sorted(blocks.items())
    ))
    total = report["totals"]
    print(f"Statement coverage: {total['percent']:.2f}% ({total['covered']}/{total['statements']})")
    return 1 if report.get("delta_percentage_points", 0) < -0.01 else 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Run the full Go suite and instrumented binary contracts, retaining failures."""
import argparse
import json
import os
from pathlib import Path
import platform
import subprocess
import sys
import tempfile


ROOT = Path(__file__).resolve().parents[2]


def capture(*args):
    return subprocess.check_output(args, cwd=ROOT, text=True).strip()


def binary_contracts(binary, output, cgo):
    with tempfile.TemporaryDirectory(prefix="brain-binary-contract-") as temporary:
        directory = Path(temporary)
        env = {k: v for k, v in os.environ.items() if not k.startswith(("ENTIRE_", "GIT_", "XDG_"))}
        env.update({key: str(directory / key) for key in (
            "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA",
            "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME", "XDG_CACHE_HOME"
        )})
        env["GOCOVERDIR"] = str(output / "binary-counters")
        cases = [("help", ["--help"], 0), ("version", ["version"], 0),
                 ("capabilities", ["capabilities", "--json"], 0),
                 ("invalid-command", ["not-a-brain-command"], 1)]
        for name, args, expected in cases:
            result = subprocess.run([str(binary), *args], cwd=directory, env=env,
                                    capture_output=True, text=True, timeout=30)
            (output / f"binary-{name}.json").write_text(json.dumps({
                "args": args, "exit_code": result.returncode,
                "stdout": result.stdout, "stderr": result.stderr,
            }, indent=2))
            if result.returncode != expected:
                raise RuntimeError(f"{name}: exit {result.returncode}, expected {expected}: {result.stderr}")
            if name == "help" and "Usage:" not in result.stdout:
                raise RuntimeError("missing CLI usage")
            if name == "version" and result.stdout.strip() != "dev":
                raise RuntimeError("unexpected unstamped version")
            if name == "invalid-command" and "unknown command" not in result.stderr:
                raise RuntimeError("missing invalid-command diagnostic")
            if name == "capabilities":
                capabilities = json.loads(result.stdout)
                if capabilities["schema_version"] != 1 or capabilities["build"]["brain_cgo"] != cgo:
                    raise RuntimeError("binary capabilities disagree with build")
        # These metadata commands must not initialize repository or user state.
        if list(directory.iterdir()):
            raise RuntimeError("read-only binary contracts created persistent state")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", required=True)
    parser.add_argument("--tags", default="")
    parser.add_argument("--race", action="store_true")
    parser.add_argument("--baseline")
    parser.add_argument("--test-timeout", default="20m",
                        help="Go test deadline per package (default: 20m)")
    args = parser.parse_args()
    output = Path(args.output).resolve()
    output.mkdir(parents=True, exist_ok=True)
    if any(output.iterdir()):
        parser.error("output directory must be empty to prevent stale coverage")
    flags = (["-race"] if args.race else []) + (["-tags", args.tags] if args.tags else [])
    metadata = {
        "commit": capture("git", "rev-parse", "HEAD"),
        "worktree_status": capture("git", "status", "--porcelain"),
        "go_version": capture("go", "version"),
        "platform": f"{platform.system()}/{platform.machine()}",
        "tags": args.tags, "race": args.race, "test_timeout": args.test_timeout,
        "scope": "./... plus instrumented binary contracts",
    }
    metadata_path = output / "environment.json"
    metadata_path.write_text(json.dumps(metadata, indent=2) + "\n")
    command = ["go", "test", *flags, "-count=1", "-timeout", args.test_timeout, "-covermode=atomic",
               "-coverpkg=./...", f"-coverprofile={output / 'tests.out'}", "-json", "./..."]
    print("Running full Go suite with cross-package coverage", flush=True)
    with (output / "tests.jsonl").open("w") as log:
        result = subprocess.run(command, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT)
    metadata["tests_exit_code"] = result.returncode
    metadata_path.write_text(json.dumps(metadata, indent=2) + "\n")
    events = []
    for line in (output / "tests.jsonl").read_text().splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if event.get("Action") in ("pass", "skip", "fail"):
            events.append({key: event[key] for key in ("Action", "Package", "Test", "Elapsed") if key in event})
    (output / "test-results.json").write_text(json.dumps(events, indent=2) + "\n")
    for event in events:
        if event["Action"] == "fail":
            print("FAIL:", event.get("Package"), event.get("Test", ""), flush=True)
    binary = output / ("entire-brain.exe" if os.name == "nt" else "entire-brain")
    subprocess.run(["go", "build", *flags, "-cover", "-covermode=atomic", "-coverpkg=./...",
                    "-o", str(binary), "./cmd/entire-brain"], cwd=ROOT, check=True)
    (output / "binary-counters").mkdir()
    binary_contracts(binary, output, "brain_cgo" in args.tags.split())
    subprocess.run(["go", "tool", "covdata", "textfmt", "-i=" + str(output / "binary-counters"),
                    "-o=" + str(output / "binary.out")], cwd=ROOT, check=True)
    report_command = [sys.executable, "-B", str(Path(__file__).with_name("report.py")),
                      str(output / "tests.out"), str(output / "binary.out"),
                      "--metadata", str(metadata_path), "--output", str(output / "summary.json"),
                      "--merged-profile", str(output / "combined.out")]
    if args.baseline:
        report_command += ["--baseline", args.baseline]
    report_result = subprocess.run(report_command, cwd=ROOT)
    if (output / "combined.out").exists():
        subprocess.run(["go", "tool", "cover", "-html=" + str(output / "combined.out"),
                        "-o", str(output / "coverage.html")], cwd=ROOT, check=True)
    return result.returncode or report_result.returncode


if __name__ == "__main__":
    raise SystemExit(main())

